str1:			db "LOAD", 0
str2:			db "SAVE", 0
str3:			db "SEQUENTIAL", 0
str4:			db "RANDOMACCESS", 0
str5:			db "MAXOPEN", 0
str6:			db "DEVICES", 0
str7:			db "VOLUMES", 0
str8:			db "HISCORE.DAT", 0
